using TMPro;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UI;

public sealed class GridShiftTutorialGuide:MonoBehaviour {
 public static Transform IntroBoard{get;private set;}static GridShiftTutorialGuide instance;
 CanvasGroup group;TMP_Text text,objective;RectTransform marker;Image diamond;int oldStep=-1;float changedAt;bool welcomeShown,completionShown;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Install(){if(instance==null){var go=new GameObject("GridShift guided learning");DontDestroyOnLoad(go);instance=go.AddComponent<GridShiftTutorialGuide>();}}
 void Awake(){var canvas=gameObject.AddComponent<Canvas>();canvas.renderMode=RenderMode.ScreenSpaceOverlay;canvas.sortingOrder=32;var scaler=gameObject.AddComponent<CanvasScaler>();scaler.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;scaler.referenceResolution=new Vector2(1920,1080);scaler.matchWidthOrHeight=.5f;
  var panel=GridShiftUI.Rect("Learning objective",transform,new Vector2(700,110));panel.anchorMin=panel.anchorMax=new Vector2(.5f,0);panel.pivot=new Vector2(.5f,0);panel.anchoredPosition=new Vector2(0,125);group=panel.gameObject.AddComponent<CanvasGroup>();group.blocksRaycasts=false;text=GridShiftUI.Text(panel,"",20,160);GridShiftUI.Stretch(text.rectTransform,new Vector2(16,12),new Vector2(-16,-12));text.overflowMode=TextOverflowModes.Ellipsis;text.alignment=TextAlignmentOptions.Center;text.fontMaterial.SetFloat("_OutlineWidth",.15f);
  marker=GridShiftUI.Rect("Current destination",transform,new Vector2(24,24));diamond=marker.gameObject.AddComponent<Image>();diamond.color=new Color(1,.82f,.15f);diamond.raycastTarget=false;marker.localRotation=Quaternion.Euler(0,0,45);objective=GridShiftUI.Text(marker,"",18,50);objective.rectTransform.sizeDelta=new Vector2(320,50);objective.rectTransform.anchoredPosition=new Vector2(0,40);objective.rectTransform.localRotation=Quaternion.Euler(0,0,-45);objective.alignment=TextAlignmentOptions.Center;
 }
 public static void HideForDialogue(){if(instance==null)return;instance.group.gameObject.SetActive(false);instance.marker.gameObject.SetActive(false);}
 public static void ResetSession(){if(instance!=null){instance.welcomeShown=false;instance.completionShown=false;instance.oldStep=-1;}}
 void OnDestroy(){if(instance==this)instance=null;}
 void Update(){var m=DeliveryManager.Instance;var scene=SceneManager.GetActiveScene();var p=m!=null?InteractionFocus.PlayerFor(m):null;bool game=p!=null&&scene.name!="MainMenu";if(game&&!m.Restoring&&m.GetComponent<DeliveryPersistence>()?.Ready==true)GridShiftTutorial.Observe(p,false,false);
  if(game&&m.Company!=null&&m.Company.Ready&&m.GetComponent<DeliveryPersistence>().Ready&&!p.ControlsBlocked&&WorldSession.Instance!=null&&!WorldSession.Instance.Busy&&!GridShiftOperationsUI.ModalOpen&&!GridShiftDepotAttendant.ModalOpen&&!GridShiftCampaignUI.ModalOpen&&Time.timeScale>0){if(GridShiftTutorial.Active&&GridShiftTutorial.Step==0&&!welcomeShown){GridShiftOperationsUI.Instance?.Open("tutorial");welcomeShown=GridShiftOperationsUI.Instance?.Current=="tutorial";}if(GridShiftTutorial.NeedsCompletion&&!completionShown){GridShiftOperationsUI.Instance?.Open("tutorial");completionShown=GridShiftOperationsUI.Instance?.Current=="tutorial";}}
  bool show=game&&!m.Restoring&&m.GetComponent<DeliveryPersistence>()?.Ready==true&&!GridShiftCampaignUI.ModalOpen&&GridShiftTutorial.Active&&!GridShiftOperationsUI.ModalOpen&&!GridShiftDepotAttendant.ModalOpen&&Time.timeScale>0&&(WorldSession.Instance==null||!WorldSession.Instance.Busy);group.gameObject.SetActive(show);marker.gameObject.SetActive(false);if(!show)return;
  int step=GridShiftTutorial.Step;if(step!=oldStep){oldStep=step;changedAt=Time.unscaledTime;group.alpha=.35f;}group.alpha=Mathf.MoveTowards(group.alpha,1,Time.unscaledDeltaTime*3);
  if(step==2&&IntroBoard==null)CreateBoard(p);
  string description=GridShiftTutorial.Instructions()[step];if(step==10){var van=m.GetComponent<GridShiftActiveOperations>()?.Van;if(van!=null)description=van.TransferBusy?"Guardando a encomenda… Aguarde a confirmação da carga.":van.CargoOrderId==GridShiftTutorial.OrderId?"Encomenda carregada! Agora entre na van e siga até o destino.":Vector3.Distance(p.transform.position,van.CargoPosition)>2.6f?"Vá até a traseira da van.":van.CargoAnimating?"Aguarde a tampa terminar de abrir.":van.CargoOpen?"Compartimento aberto. Pressione "+GridShiftControls.KeyName(GSAction.Interact)+" para guardar a caixa.":"Pressione "+GridShiftControls.KeyName(GSAction.Interact)+" para abrir o compartimento.";}
  if(step!=10&&GridShiftTutorial.ExtraHints&&Time.unscaledTime-changedAt>40){string[] hints={"Comece pelo botão COMEÇAR da ajuda.","Caminhe em uma área livre. Corra para a frente e mova o mouse para olhar.","Procure Carlos, seu mentor, e converse com ele usando E.","Abrir o tablet ainda não basta: selecione a aba Entregas.","Procure a porta identificada GS na Factory e mire nela ao alcance da interação.","A recepção fica à esquerda da entrada. Converse e use Encerrar conversa.","Consulte o monitor de pedidos à direita e confirme o pedido disponível.","Compare o ID do pedido com a caixa marcada. Mire na caixa, em vez da estante decorativa.","Leve a caixa em mãos até o leitor da mesa de conferência à esquerda.","Siga o marcador da próxima bancada. Quando estiver pronta, saia levando a caixa.","Vá à abertura traseira. Use a mesma interação para abrir e depois guardar a caixa.","Consulte o mapa enquanto dirige. Só avance depois de mover a van com a carga.","Pare perto do cliente, saia da van e retire a encomenda da traseira.","Caminhe até a entrada do cliente com a caixa em mãos e confirme a interação.","No tablet, selecione Financeiro para consultar o pagamento recebido.","Use Salvar Jogo no menu de pausa."};description=hints[step];}
  text.text="<color=#FFD23F>"+(step<2?"PRIMEIROS PASSOS · ":"CARLOS · ")+""+(step+1)+" · "+GridShiftTutorial.Titles[step]+"</color>\n"+description+"\n<size=16><color=#ABB6C2>"+GridShiftControls.KeyName(GSAction.Tutorial)+" · COMO JOGAR</color></size>";
  if(GridShiftTutorial.TryObjective(out var at,out var name)&&Camera.main!=null){var screen=Camera.main.WorldToScreenPoint(at+Vector3.up*.6f);if(screen.z<0){screen.x=Screen.width-screen.x;screen.y=Screen.height*.15f;}screen.x=Mathf.Clamp(screen.x,Screen.width*.09f,Screen.width*.91f);screen.y=Mathf.Clamp(screen.y,Screen.height*.32f,Screen.height*.75f);RectTransformUtility.ScreenPointToLocalPointInRectangle((RectTransform)transform,screen,null,out var local);marker.anchoredPosition=local;marker.gameObject.SetActive(true);objective.text=name+"\n"+Vector3.Distance(p.transform.position,at).ToString("0")+" m";}
 }
 void CreateBoard(PlayerMovement player){IntroBoard=GridShiftMentor.Carlos;}
